"""Memory keyed account_id+person_id. No global secrets file."""

from __future__ import annotations

import copy

from hades_runtime.physics import apply_elapsed, inner_life_jobs, parse_time
from hades_runtime.state import (
    account_id_from_auth,
    clamp_character_patch,
    zero_account,
)


class Store:
    def __init__(self) -> None:
        self._data: dict[tuple[str, str], dict] = {}
        self._accounts: dict[str, dict] = {}

    def write(self, account_id: str, person_id: str, payload: dict) -> None:
        if account_id and account_id not in self._accounts:
            self._accounts[account_id] = zero_account(account_id)
            self._persist_account(account_id)
        key = (account_id, person_id)
        row = dict(self._data.get(key) or {})
        row.update(payload)
        self._data[key] = row

    def read(self, account_id: str, person_id: str, field: str | None = None):
        row = self._data.get((account_id, person_id)) or {}
        if field is None:
            return dict(row)
        return row.get(field)

    def list_people(self, account_id: str) -> list[str]:
        return sorted(person_id for acc, person_id in self._data if acc == account_id)

    def create_account(self, account_id: str, timezone: str = "UTC") -> dict:
        if not account_id:
            raise ValueError("no account_id")
        if account_id not in self._accounts:
            self._accounts[account_id] = zero_account(account_id, timezone)
            self._persist_account(account_id)
        return self.get_account(account_id)

    def get_account(self, account_id: str) -> dict | None:
        row = self._accounts.get(account_id)
        if row is None:
            return None
        return copy.deepcopy(row)

    def get_account_for_request(
        self, token_account_id: str, body_account_id: str | None = None
    ) -> dict:
        account_id = account_id_from_auth(token_account_id, body_account_id)
        existing = self.get_account(account_id)
        if existing is not None:
            return existing
        return self.create_account(account_id)

    def set_opted_in_inner_life(self, account_id: str, opted_in: bool) -> None:
        if not account_id:
            raise ValueError("no account_id")
        if account_id not in self._accounts:
            self._accounts[account_id] = zero_account(account_id)
        self._accounts[account_id]["opted_in_inner_life"] = bool(opted_in)
        self._persist_account(account_id)

    def set_timestamps(self, account_id: str, *, last_tick=None, last_inbound=None) -> None:
        if not account_id:
            raise ValueError("no account_id")
        if account_id not in self._accounts:
            self._accounts[account_id] = zero_account(account_id)
        if last_tick is not None:
            stamp = parse_time(last_tick)
            self._accounts[account_id]["last_tick"] = stamp.isoformat() if stamp else None
        if last_inbound is not None:
            stamp = parse_time(last_inbound)
            self._accounts[account_id]["last_inbound"] = stamp.isoformat() if stamp else None
        self._persist_account(account_id)

    def apply_elapsed(self, account_id: str, now) -> dict:
        if not account_id:
            raise ValueError("no account_id")
        if account_id not in self._accounts:
            self._accounts[account_id] = zero_account(account_id)
        row = self._accounts[account_id]
        cs, _meta = apply_elapsed(
            row["character_state"],
            timezone_name=row.get("timezone") or "UTC",
            last_tick=row.get("last_tick"),
            now=parse_time(now),
        )
        row["character_state"] = cs
        row["last_tick"] = parse_time(now).isoformat()
        self._persist_account(account_id)
        return self.get_account(account_id)

    def inner_life_jobs(self, account_id: str, now) -> int:
        row = self._accounts.get(account_id)
        if not row:
            return 0
        return inner_life_jobs(
            row.get("last_inbound"),
            parse_time(now),
            opted_in=bool(row.get("opted_in_inner_life")),
        )

    def tick_account(
        self, account_id: str, character_patch: dict | None = None, now=None
    ) -> dict:
        if not account_id:
            raise ValueError("no account_id")
        if account_id not in self._accounts:
            self._accounts[account_id] = zero_account(account_id)
        if now is not None:
            self.apply_elapsed(account_id, now)
        if character_patch:
            cs = dict(self._accounts[account_id]["character_state"])
            cs.update(clamp_character_patch(character_patch))
            self._accounts[account_id]["character_state"] = cs
        self._persist_account(account_id)
        return self.get_account(account_id)

    def _persist_account(self, account_id: str) -> None:
        return


class FileStore(Store):
    def __init__(self, root) -> None:
        super().__init__()
        from pathlib import Path
        import json

        self._root = Path(root)
        self._root.mkdir(parents=True, exist_ok=True)
        self._json = json
        self._load()

    def _path(self, account_id: str, person_id: str):
        safe = f"{account_id}__{person_id}.json".replace("/", "_")
        return self._root / safe

    def _account_path(self, account_id: str):
        safe = f"{account_id}.account.json".replace("/", "_")
        return self._root / safe

    def _load(self) -> None:
        for path in self._root.glob("*.account.json"):
            row = self._json.loads(path.read_text(encoding="utf-8"))
            self._accounts[row["account_id"]] = row
        for path in self._root.glob("*.json"):
            if path.name.endswith(".account.json"):
                continue
            row = self._json.loads(path.read_text(encoding="utf-8"))
            acc, person = row["account_id"], row["person_id"]
            data = dict(row)
            data.pop("account_id", None)
            data.pop("person_id", None)
            self._data[(acc, person)] = data

    def write(self, account_id: str, person_id: str, payload: dict) -> None:
        super().write(account_id, person_id, payload)
        row = {
            "account_id": account_id,
            "person_id": person_id,
            **self._data[(account_id, person_id)],
        }
        self._path(account_id, person_id).write_text(
            self._json.dumps(row), encoding="utf-8"
        )

    def _persist_account(self, account_id: str) -> None:
        row = self._accounts[account_id]
        self._account_path(account_id).write_text(
            self._json.dumps(row), encoding="utf-8"
        )

