"""Founder import. Gitignored name map. Never commit relations.yaml."""

from __future__ import annotations

import json
from pathlib import Path

from hades_runtime.store import Store


def load_name_map(path) -> dict:
    p = Path(path)
    if not p.name.endswith(".local.json"):
        raise ValueError("name map must be gitignored *.local.json")
    return json.loads(p.read_text(encoding="utf-8"))


def import_founder(
    store: Store,
    account_id: str,
    snapshot: dict,
    name_map: dict,
    timezone: str | None = None,
) -> dict:
    if not account_id:
        raise ValueError("no account_id")
    if not name_map:
        raise ValueError("name map required")
    tz = timezone or snapshot.get("timezone") or "UTC"
    store.create_account(account_id, timezone=tz)
    cs = snapshot.get("character_state") or {}
    store.tick_account(account_id, cs)
    if snapshot.get("opted_in_inner_life"):
        store.set_opted_in_inner_life(account_id, True)
    for person in snapshot.get("people") or []:
        raw = person.get("name")
        if raw not in name_map:
            raise ValueError("unmapped person")
        ident = name_map[raw]
        store.write(
            account_id,
            ident["person_id"],
            {
                "center": person.get("center") or 0.0,
                "depth": person.get("depth") or 0.0,
                "secrets": list(person.get("secrets") or []),
                "episodic": list(person.get("episodic") or []),
                "flags": {
                    "is_partner": bool(ident.get("is_partner")),
                    "is_family": bool(ident.get("is_family")),
                },
            },
        )
    return store.get_account(account_id)

"""Account character_state. Native scales. Auth token is account_id."""

from __future__ import annotations

SCHEMA_VERSION = "1"

MOOD_MIN = -10.0
MOOD_MAX = 10.0
FATIGUE_MIN = 0.0
FATIGUE_MAX = 6.0
DEPTH_MIN = 0.0
DEPTH_MAX = 200.0

CHARACTER_KEYS = (
    "effective_mood",
    "residual",
    "itd",
    "fatigue",
    "circadian",
    "lock",
    "place",
)


def clamp_mood(value: float) -> float:
    return max(MOOD_MIN, min(MOOD_MAX, float(value)))


def clamp_fatigue(value: float) -> float:
    return max(FATIGUE_MIN, min(FATIGUE_MAX, float(value)))


def clamp_depth(value: float) -> float:
    return max(DEPTH_MIN, min(DEPTH_MAX, float(value)))


def zero_character_state() -> dict:
    return {
        "effective_mood": 0.0,
        "residual": 0.0,
        "itd": 0.0,
        "fatigue": 0.0,
        "circadian": 0.0,
        "lock": None,
        "place": None,
    }


def zero_inner_life() -> dict:
    return {"thoughts": []}


def zero_account(account_id: str, timezone: str = "UTC") -> dict:
    return {
        "schema_version": SCHEMA_VERSION,
        "account_id": account_id,
        "timezone": timezone or "UTC",
        "character_state": zero_character_state(),
        "inner_life": zero_inner_life(),
        "last_inbound": None,
        "last_tick": None,
        "opted_in_inner_life": False,
    }


def clamp_character_patch(patch: dict) -> dict:
    out: dict = {}
    for key in CHARACTER_KEYS:
        if key not in patch:
            continue
        value = patch[key]
        if key == "effective_mood":
            out[key] = clamp_mood(value)
        elif key == "fatigue":
            out[key] = clamp_fatigue(value)
        elif key in ("lock", "place"):
            out[key] = value
        else:
            out[key] = float(value)
    return out


def account_id_from_auth(
